<script setup lang="ts">import {computed} from 'vue';import type {Risk,Task} from '../types/domain';import {num,pct} from '../utils/format';const props=defineProps<{risk:Risk;tasks:Task[]}>();const res=computed(()=>props.risk.resource);const rows=computed(()=>(res.value?.task_resource_wait??[]).slice().sort((a,b)=>b.wait_share-a.wait_share||a.task_id.localeCompare(b.task_id)));const name=(id:string)=>props.tasks.find(t=>t.task_id===id)?.name;</script><template><template v-if="res"><div class="quantiles"><span>班组导致延期的样本 <b>{{res.delayed_count}} / {{risk.samples}}</b></span><span>平均延期 <b>{{num(res.mean_delay)}}h</b></span><span>最大延期 <b>{{num(res.max_delay)}}h</b></span></div><div class="criticality-list"><div v-for="r in rows" :key="r.task_id" class="criticality-row"><span><b>{{r.task_id}}</b> {{name(r.task_id)}}</span><div class="bar-track"><i :style="{width:(r.wait_share*100)+'%'}"/></div><strong>{{pct(r.wait_share)}}</strong><small>均值{{num(r.mean_wait)}}h · 峰值{{num(r.max_wait)}}h · {{r.wait_count}}/{{r.denominator}}</small></div></div><p class="muted">资源等待=开工−全部前置完工就绪时刻；比例为等待超过{{risk.tolerance_hours}}小时的样本份额，分母为全部{{risk.samples}}次抽样。延期=班组受限完工−同样本无约束CPM完工（{{res.delay_basis}}）。</p></template></template>